INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein API-Key die einzige Authentifizierungsmethode?', 2, '[{"text": "Nein", "correct": true, "because": "OAuth und andere existieren"}, {"text": "Ja", "correct": false, "because": "Mehrere Optionen verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit OAuth?', 3, '[{"text": "Sichere Autorisierung", "correct": true, "because": "Delegiert Zugriff"}, {"text": "Datenbankzugriff", "correct": false, "because": "Kein direkter Bezug"}, {"text": "UI-Anpassung", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutze ich für Authentifizierung?', 5, '[{"text": "API-Keys", "correct": true, "because": "Einfache Identifikation"}, {"text": "OAuth", "correct": true, "because": "Token-basierte Autorisierung"}, {"text": "CSS", "correct": false, "because": "Kein Sicherheitsmechanismus"}, {"text": "HTML", "correct": false, "because": "Kein Authentifizierungsprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) API-Keys sind statisch. b) OAuth benötigt keine Tokens.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "OAuth nutzt Tokens"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Authentifizierung?', 4, '[{"text": "Sicherheitsprotokoll", "correct": false, "because": "Schützt Zugriff"}, {"text": "Schlüsselverwaltung", "correct": false, "because": "Wichtig für Sicherheit"}, {"text": "Farbschema", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob OAuth nur für Web-Anwendungen ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Mobile nutzbar"}, {"text": "Ja", "correct": false, "because": "Breiter einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für einfache Zugriffskontrolle?', 3, '[{"text": "API-Key", "correct": true, "because": "Einfach zu implementieren"}, {"text": "OAuth", "correct": false, "because": "Komplexer mit Tokens"}, {"text": "XML", "correct": false, "because": "Format, keine Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat OAuth?', 5, '[{"text": "Token-basiert", "correct": true, "because": "Nutzt Zugriffstoken"}, {"text": "Delegierte Autorisierung", "correct": true, "because": "Dritte autorisieren"}, {"text": "Statische Schlüssel", "correct": false, "because": "Dynamische Tokens"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) API-Keys sind unsicher. b) OAuth ist immer kompliziert. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) kontextabhängig, b) vereinfachbar"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) nicht pauschal"}, {"text": "Beides stimmt", "correct": false, "because": "Beides kontextuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Authentifizierung?', 4, '[{"text": "Schlüssel oder Token", "correct": false, "because": "Identifizieren Nutzer"}, {"text": "Sicherer Transport", "correct": false, "because": "Schützt Daten"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind API-Keys immer geheim?', 2, '[{"text": "Ja", "correct": true, "because": "Schützen Zugriff"}, {"text": "Nein", "correct": false, "because": "Sollten geheim sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zu OAuth?', 4, '[{"text": "Autorisierung anfordern", "correct": true, "because": "Nutzer gibt Zustimmung"}, {"text": "Token austauschen", "correct": true, "because": "Zugriff gewähren"}, {"text": "UI neu laden", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass API-Keys OAuth ersetzen können. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Unterschiedliche Zwecke"}, {"text": "Ja", "correct": false, "because": "OAuth komplexer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Authentifizierung?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schützt Ressourcen"}, {"text": "Schnelle Einrichtung", "correct": false, "because": "Sicherheit zählt mehr"}, {"text": "Designanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) OAuth nutzt Redirects. b) API-Keys sind temporär.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "API-Keys meist statisch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei Authentifizierung?', 5, '[{"text": "Schlüsselverlust", "correct": true, "because": "Zugriff gefährdet"}, {"text": "Token-Missbrauch", "correct": true, "because": "Sicherheit beeinträchtigt"}, {"text": "Schnellere API", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Authentifizierung unwichtig?', 3, '[{"text": "Schlüsselverwaltung", "correct": false, "because": "Sichert Zugriff"}, {"text": "Protokollsicherheit", "correct": false, "because": "Schützt Übertragung"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann OAuth ohne Nutzerinteraktion laufen?', 3, '[{"text": "Ja", "correct": true, "because": "Client-Credentials-Flow"}, {"text": "Nein", "correct": false, "because": "Interaktion oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob API-Keys ablaufen?', 2, '[{"text": "Nein", "correct": true, "because": "Meist statisch"}, {"text": "Ja", "correct": false, "because": "Nur bei spezifischer Konfig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für delegierten Zugriff?', 4, '[{"text": "OAuth", "correct": true, "because": "Sicherer Token-Austausch"}, {"text": "API-Key", "correct": false, "because": "Einfacher, weniger sicher"}, {"text": "XML", "correct": false, "because": "Nur Format"}]');
